def split_names(apps, schema_editor):
    """Every name so far was one field: the first word is the first name, the
    last word the last name, anything between the middle name. Records
    corrects any it got wrong; the whole name is not touched."""
    StudentProfile = apps.get_model('attendance', 'StudentProfile')
    for profile in StudentProfile.objects.all().only('id', 'name'):
        words = (profile.name or '').split()
        if not words:
            continue
        first, last = words[0], (words[-1] if len(words) > 1 else '')
        middle = ' '.join(words[1:-1]) if len(words) > 2 else ''
        StudentProfile.objects.filter(pk=profile.pk).update(
            first_name=first[:80], middle_name=middle[:80], last_name=last[:80])


